# Lunar Konstruksi - Fase 7.3 Construction Reference Match
Set-StrictMode -Version Latest
$ErrorActionPreference = "Stop"

function P([string]$m){Write-Host "[FASE 7.3] $m" -ForegroundColor Cyan}
function F([string]$m){Write-Host "[FASE 7.3] GAGAL: $m" -ForegroundColor Red;exit 1}
function W([string]$p,[string]$c){$d=Split-Path -Parent $p;if($d -and -not(Test-Path -LiteralPath $d)){New-Item -ItemType Directory -Force -Path $d|Out-Null};$e=New-Object System.Text.UTF8Encoding($false);[IO.File]::WriteAllText($p,$c,$e)}
function D([string]$v){[Text.Encoding]::UTF8.GetString([Convert]::FromBase64String($v))}
$root=(& git rev-parse --show-toplevel 2>$null);if(-not $root){F "Jalankan dari root repository."};$root=$root.Trim();Set-Location $root
$dirty=& git status --porcelain --untracked-files=no;if($dirty){Write-Host $dirty;F "Commit/stash perubahan tracked sebelum apply."}
$req=@("package.json","features/public-site/server.ts","components/site/home-page.tsx","components/site/site-header.tsx","components/site/site-footer.tsx","components/site/redesign/public-contact-form.tsx","features/leads/lead.types.ts")
$miss=@($req|?{-not(Test-Path -LiteralPath $_)});if($miss.Count){$miss|%{Write-Host " - $_"};F "Fondasi Fase 1-7 belum lengkap."}
P "Mengganti homepage dengan reference-match composition..."
$payload=@{}
$payload["PHASE7_3_REFERENCE_MATCH.md"]=""
$payload["components/site/home-page.tsx"]=""
$payload["components/site/redesign/public-contact-form.tsx"]=""
$payload["components/site/redesign/public-footer.tsx"]=""
$payload["components/site/redesign/public-header.tsx"]=""
$payload["components/site/redesign/reference-home.tsx"]=""
foreach($x in $payload.GetEnumerator()){W (Join-Path $root $x.Key) (D $x.Value);Write-Host "[FASE 7.3] write $($x.Key)" -ForegroundColor DarkGray}
Write-Host "";Write-Host "[FASE 7.3] Selesai. Tidak ada dependency baru." -ForegroundColor Green
Write-Host "Jalankan: npm run dev"
Write-Host "Lalu: npm run typecheck; npm run build; git diff --check"
